function academy(){return '<div class="card"><h2>青训中心 · VOLT Lab</h2><p class="muted">每周试训、培养潜力选手，升级设施可提升发现率。</p><button class="btn" onclick="toast(\"已生成青训报告\")">生成本周报告</button></div>'}function finance(){return '<div class="grid stats"><div class="card"><span class="stat-label">月度工资</span><div class="stat-value">¥ 86K</div></div><div class="card"><span class="stat-label">赞助收入</span><div class="stat-value">¥ 0</div><p class="muted">声望达到 2,000 解锁</p></div></div>'}function roster(){const q=state.rosterQuery||'';const region=state.rosterRegion||'全部';const role=state.rosterRole||'全部';const list=players.filter(p=>(!q||p.join(' ').toLowerCase().includes(q.toLowerCase()))&&(region==='全部'||p[4]===region)&&(role==='全部'||p[2].includes(role)));return `<div class="hero"><div><span class="eyebrow">GLOBAL VCT DATABASE · ${players.length} PLAYERS</span><h2>全球选手市场</h2><p>浏览球员资料，发起试训并打造你的首发阵容。</p></div><button class="btn" onclick="refreshScouting()">刷新球探报告</button></div><div class="tabs"><input class="search" placeholder="搜索 ID、姓名或战队" value="${q}" oninput="state.rosterQuery=this.value;render()"><button onclick="state.rosterRegion='全部';render()">全部 ${players.length}</button><button onclick="state.rosterRegion='CN';render()">CN</button><button onclick="state.rosterRegion='Pacific';render()">Pacific</button><button onclick="state.rosterRegion='EMEA';render()">EMEA</button><button onclick="state.rosterRegion='Americas';render()">Americas</button></div><div class="tabs"><button onclick="state.rosterRole='全部';render()">全部定位</button><button onclick="state.rosterRole='Duelist';render()">决斗者</button><button onclick="state.rosterRole='Initiator';render()">发起者</button><button onclick="state.rosterRole='Controller';render()">控场者</button><button onclick="state.rosterRole='Sentinel';render()">哨卫</button><span class="muted">找到 ${list.length} 名选手 · 已签约 ${state.signed.length} 人</span></div><div class="grid player-grid">${list.map(p=>`<div class="card player"><div class="player-top"><div class="portrait">${p[0][0].toUpperCase()}</div><div><h3>${p[0]}</h3><small>${p[1]} · ${p[3]}</small><div class="role">${p[2]} · ${p[4]}</div></div></div><div class="player-foot"><span>${p[5]} / 年</span><button class="btn alt" onclick="sign('${p[0]}')">${state.signed.includes(p[0])?'已签约':'发起洽谈'}</button></div></div>`).join('')}</div>`}
function club(){const lineup=state.signed.slice(0,5).map((n,i)=>{const p=players.find(x=>x[0]===n);return p?`<div class="tactic"><div><b>${['Duelist','Initiator','Controller','Sentinel','Flex'][i]} · ${p[0]}</b><small>${p[1]} · ${p[3]}</small></div><button class="btn alt" onclick="releasePlayer('${p[0]}')">释放</button></div>`:''}).join('');return `<div class="grid columns"><section class="card"><div class="card-head"><h2>VOLT Academy</h2><span class="badge">${state.signed.length}/5 首发</span></div><h2 style="font-size:25px">从青训到世界舞台</h2><p class="muted">成立于 2025 · 上海，中国</p>${lineup||'<div class="empty">还没有签约选手。前往选手市场组建你的首发阵容。</div>'}<button class="btn" onclick="goRoster()">前往选手市场</button></section><section class="card"><div class="card-head"><h2>俱乐部目标</h2><span class="tag">SEASON</span></div><div class="tactic"><b>完成首发阵容</b><span class="trend">${Math.min(5,state.signed.length)} / 5</span></div><div class="tactic"><b>赢得正式比赛</b><span class="trend">${state.wins||0} 胜</span></div><div class="tactic"><b>俱乐部声望</b><span class="trend">${state.reputation}</span></div></section></div>`}
function schedule(){return `<div class="grid columns"><section class="card wide"><div class="card-head"><h2>VCT CN 2025 · 第二赛段</h2><span class="badge">进行中</span></div>${[['JUN 18','VOLT Academy','Nova Esports','常规赛'],['JUN 24','Bilibili Gaming','VOLT Academy','常规赛'],['JUL 02','VOLT Academy','EDward Gaming','季后赛']].map(x=>`<div class="schedule-row"><small>${x[0]}</small><b>${x[1]} <span class="muted">vs</span> ${x[2]}</b><span class="badge">${x[3]}</span><small>BO3 · 19:00</small></div>`).join('')}</section><section class="card"><div class="card-head"><h2>赛事日历</h2></div><div class="news"><span class="tag">MASTERS</span><b>多伦多大师赛</b><small>6月7日 — 6月22日 · Riot Games</small></div><div class="news"><span class="tag">CHAMPIONS</span><b>VCT Champions 2025</b><small>9月12日 — 10月5日 · 巴黎</small></div></section></div>`}
function tactics(){return `<div class="grid columns"><section class="card"><div class="card-head"><h2>战术与训练计划</h2><button class="btn" onclick="toast('训练计划已保存')">保存计划</button></div><div class="tactic"><div><b>进攻回合：快攻节奏</b><small>提升首杀率 · 降低经济稳定性</small></div><div class="switch on" onclick="this.classList.toggle('on')"></div></div><div class="tactic"><div><b>防守回合：默认控图</b><small>提升中后期胜率 · 需要高沟通</small></div><div class="switch on" onclick="this.classList.toggle('on')"></div></div><div class="tactic"><div><b>每周团队建设</b><small>化学反应 +6 · 消耗 ¥12,000</small></div><div class="switch" onclick="this.classList.toggle('on')"></div></div></section><section class="card"><div class="card-head"><h2>地图胜率</h2></div><div class="news"><b>莲华古城 · 72%</b><div class="bar"><em style="width:72%"></em></div></div><div class="news"><b>日落之城 · 64%</b><div class="bar"><em style="width:64%"></em></div></div><div class="news"><b>深海明珠 · 48%</b><div class="bar"><em style="width:48%;background:var(--red)"></em></div></div></section></div>`}
function club(){return `<div class="grid columns"><section class="card"><div class="card-head"><h2>VOLT Academy</h2><span class="badge">独立战队</span></div><h2 style="font-size:25px">从青训到世界舞台</h2><p class="muted">俱乐部成立于 2025 · 上海，中国</p><div class="news"><b>主场：上海电竞中心</b><small>设施等级 1 · 可容纳 120 人</small></div><div class="news"><b>赞助商：暂无</b><small>提升声望后可解锁品牌合作</small></div></section><section class="card"><div class="card-head"><h2>管理目标</h2></div><div class="tactic"><b>签下第一位选手</b><span class="trend">完成</span></div><div class="tactic"><b>赢得一场正式比赛</b><span class="muted">0 / 1</span></div><div class="tactic"><b>俱乐部声望达到 2,000</b><span class="muted">1,240 / 2,000</span></div></section></div>`}
function render(){page.innerHTML=({dashboard,roster,schedule,tactics,club,academy,finance}[state.page])();document.querySelector('#page-title').textContent=pageTitle[state.page];document.querySelector('#page-domain').textContent=pageDomains[state.page]+' · MONDAY · WEEK 04';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;render()})}function sign(name){const p=players.find(x=>x[0]===name);if(!p)return;if(state.signed.includes(name)){toast('该选手已经签约');return}if(state.signed.length>=5){toast('首发阵容已满，请先释放一名选手');return}const cost=parseInt(p[5].replace(/[^0-9]/g,''))*1000;if(state.money<cost){toast('预算不足，无法完成签约');return}state.money-=cost;state.signed.push(name);state.chemistry=Math.min(100,state.chemistry+3);state.reputation+=25;save();toast('已签约 '+name+'，加入首发阵容');render()}function toast(s){let t=document.querySelector('#toast');t.textContent=s;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;const url=Object.keys(pathPages).find(k=>pathPages[k]===state.page)||'/';history.pushState({},'',BASE+(url==='/'?'/' :(url.endsWith('/')?url:url+'/')));render()});window.addEventListener('popstate',()=>{state.page=pathPages[routePath()]||'dashboard';render()});
function dashboard(){return `<div class="hero"><div><span class="eyebrow">WEEK ${state.week} · MANAGEMENT PHASE</span><h2>你的时代，从今天开始。</h2><p>完成每日管理行动，提升战队实力并争取晋级。</p></div><button class="btn" onclick="advanceWeek()">推进一周</button></div>${cardStats()}<div class="grid columns"><section class="card"><div class="card-head"><h2>本周管理行动</h2><span class="badge">${state.actions||0} / 3</span></div><div class="tactic"><div><b>安排团队训练</b><small>化学反应 +5 · 费用 ¥8,000</small></div><button class="btn alt" onclick="doAction('训练')">执行</button></div><div class="tactic"><div><b>派遣全球球探</b><small>发现一名潜力选手</small></div><button class="btn alt" onclick="doAction('球探')">执行</button></div><div class="tactic"><div><b>联系赞助品牌</b><small>获得一次商业谈判机会</small></div><button class="btn alt" onclick="doAction('赞助')">执行</button></div><div class="tactic"><div><b>处理今日突发事件</b><small>随机事件 · 影响战队状态</small></div><button class="btn alt" onclick="randomEvent()">处理</button></div></section><section class="card"><div class="card-head"><h2>联盟动态</h2><span class="tag">LIVE</span></div><div class="news"><b>自由选手市场正在升温</b><small>把握窗口期，完成你的第一笔签约</small></div><div class="news"><b>下场比赛：VOLT Academy vs Nova</b><small>5天后 · VCT CN 常规赛 · BO3</small></div></section></div>`}
function schedule(){return `<div class="grid columns"><section class="card wide"><div class="card-head"><h2>VCT CN 2025 · 第二赛段</h2><button class="btn" onclick="simulateMatch()">模拟下一场</button></div>${[['JUN 18','VOLT Academy','Nova Esports','常规赛'],['JUN 24','Bilibili Gaming','VOLT Academy','常规赛'],['JUL 02','VOLT Academy','EDward Gaming','季后赛']].map(x=>`<div class="schedule-row"><small>${x[0]}</small><b>${x[1]} <span class="muted">vs</span> ${x[2]}</b><span class="badge">${x[3]}</span><small>BO3 · 19:00</small></div>`).join('')}</section><section class="card"><div class="card-head"><h2>赛季战绩</h2></div><div class="stat-value">${state.wins||0} - ${state.losses||0}</div><p class="muted">胜率 ${((state.wins||0)/Math.max(1,(state.wins||0)+(state.losses||0))*100).toFixed(0)}%</p><div class="news"><b>比赛准备度</b><div class="bar"><em style="width:${Math.min(100,55+(state.actions||0)*8)}%"></em></div></div></section></div>`}
function academy(){return `<div class="grid columns"><section class="card"><div class="card-head"><h2>青训中心 · VOLT Lab</h2><button class="btn" onclick="recruitProspect()">招募新人</button><button class="btn alt" onclick="upgradeFacility()">升级设施</button></div><p class="muted">培养潜力选手，建设属于你的未来阵容。</p><div class="news"><b>设施等级 1</b><small>升级费用 ¥120,000 · 发现率 +10%</small></div><div class="news"><b>本周潜力评估：A-</b><small>建议继续投入团队训练</small></div></section><section class="card"><h2>培养方向</h2><div class="tactic"><b>枪法训练</b><span class="trend">+ Duelist</span></div><div class="tactic"><b>沟通训练</b><span class="trend">+ IGL</span></div></section></div>`}
function finance(){return `<div class="grid stats"><div class="card"><span class="stat-label">当前预算</span><div class="stat-value">¥ ${state.money.toLocaleString()}</div></div><div class="card"><span class="stat-label">赛季奖金</span><div class="stat-value">¥ ${((state.wins||0)*25000).toLocaleString()}</div></div><div class="card"><span class="stat-label">赞助合同</span><div class="stat-value">${state.sponsor?'已签署':'待洽谈'}</div><button class="btn alt" onclick="signSponsor()">${state.sponsor?'查看合同':'谈判赞助'}</button></div></div>`}
function doAction(type){if((state.actions||0)>=3){toast('本周行动次数已用完');return}state.actions=(state.actions||0)+1;if(type==='训练'){state.money=Math.max(0,state.money-8000);state.chemistry=Math.min(100,state.chemistry+5);state.morale=Math.min(100,state.morale+3)}if(type==='球探')state.reputation+=30;if(type==='赞助')state.sponsor=true;checkAchievements();save();toast(type+'行动已完成');render()}
function advanceWeek(){state.week++;state.actions=0;state.morale=Math.max(0,state.morale-1);state.log.unshift('Week '+state.week+' started');save();toast('新的一周开始了');render()}
function simulateMatch(){if((state.actions||0)<1){toast('请先完成至少一项赛前准备');return}Math.random()>.38?(state.wins=(state.wins||0)+1,toast('比赛胜利！声望提升')):(state.losses=(state.losses||0)+1,toast('比赛失利，继续调整战术'));state.actions=0;state.reputation+=(state.wins>state.losses?100:20);checkAchievements();save();render()}
function recruitProspect(){if(state.money<30000){toast('预算不足');return}state.money-=30000;state.morale=Math.min(100,state.morale+2);toast('新潜力选手已加入试训名单');save();render()}
function randomEvent(){if((state.actions||0)>=3){toast('本周行动次数已用完');return}const e=events[Math.floor(Math.random()*events.length)];state.actions++;e[2]();state.log.unshift(e[0]+': '+e[1]);save();toast(e[0]+'：'+e[1]);render()}
function upgradeFacility(){const cost=state.facility*120000;if(state.money<cost){toast('预算不足，需要 ¥'+cost.toLocaleString());return}state.money-=cost;state.facility++;state.chemistry=Math.min(100,state.chemistry+8);checkAchievements();save();toast('训练设施升级成功');render()}
function signSponsor(){state.sponsor=true;state.money+=50000;toast('赞助谈判成功，获得 ¥50,000');save();render()}
function goRoster(){state.page='roster';history.pushState({},'', BASE+'/roster/');render()}
function refreshScouting(){state.scoutBonus=(state.scoutBonus||0)+1;toast('球探报告已更新，发现率提升');render()}
function releasePlayer(name){state.signed=state.signed.filter(x=>x!==name);save();toast(name+' 已离开首发名单');render()}
function save(){localStorage.setItem('volt-save',JSON.stringify({money:state.money,week:state.week,actions:state.actions,wins:state.wins,losses:state.losses,morale:state.morale,chemistry:state.chemistry,facility:state.facility,reputation:state.reputation,sponsor:state.sponsor,achievements:state.achievements,log:state.log,signed:state.signed}))}
Object.assign(state,{week:4,money:1250000,actions:0,wins:0,losses:0,morale:72,chemistry:68,facility:1,reputation:1240,achievements:[],log:[],signed:[],rosterRegion:'全部'},JSON.parse(localStorage.getItem('volt-save')||'{}'));
const events=[['媒体采访','接受采访，提升声望但消耗时间。',()=>{state.reputation+=80;state.morale-=2}],['临时训练赛','参加高强度训练赛，可能获得额外收益。',()=>{state.chemistry+=4;state.morale+=5}],['设备故障','训练室设备需要维修。',()=>{state.money=Math.max(0,state.money-15000);state.chemistry-=2}]];
function checkAchievements(){const list=[state.wins>=1&&'首胜',state.wins>=3&&'连战连胜',state.reputation>=2000&&'地区明星',state.sponsor&&'商业伙伴',state.facility>=2&&'训练基地'];list.filter(Boolean).forEach(x=>{if(!state.achievements.includes(x)){state.achievements.push(x);toast('成就解锁：'+x)}})}
function save(){localStorage.setItem('volt-save',JSON.stringify({money:state.money,week:state.week,actions:state.actions,wins:state.wins,losses:state.losses,morale:state.morale,chemistry:state.chemistry,facility:state.facility,reputation:state.reputation,sponsor:state.sponsor,achievements:state.achievements,log:state.log,signed:state.signed}))}function render(){page.innerHTML=({dashboard,roster,schedule,tactics,club,academy,finance}[state.page])();document.querySelector('#page-title').textContent=pageTitle[state.page];document.querySelector('#page-domain').textContent=pageDomains[state.page]+' · WEEK '+state.week;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{state.page=b.dataset.page;const url=Object.keys(pathPages).find(k=>pathPages[k]===state.page)||'/';history.pushState({},'',BASE+(url==='/'?'/' :(url.endsWith('/')?url:url+'/')));render()});document.querySelector('#money').textContent='¥ '+state.money.toLocaleString()}
document.addEventListener('click',function(e){const b=e.target.closest('nav button[data-page]');if(b){e.preventDefault();state.page=b.dataset.page;const u=Object.keys(pathPages).find(k=>pathPages[k]===state.page)||'/';history.pushState({},'',BASE+(u==='/'?'/' :(u.endsWith('/')?u:u+'/')));render()}});render();
render();

// Gameplay pack: weekly missions and pre-match preparation, added without replacing page templates.
Object.assign(state,{prep:state.prep||0,missions:state.missions||{training:0,analysis:0,win:0},eventsSeen:state.eventsSeen||0});
function gameplaySave(){localStorage.setItem('volt-save',JSON.stringify({...state}))}
function gameplayPanel(){const m=state.missions;return `<section class="card"><div class="card-head"><h2>本周玩法目标</h2><span class="badge">${m.training+m.analysis+m.win}/3</span></div><div class="tactic"><div><b>强化团队训练</b><small>化学反应 +3 · 准备度 +10</small></div><button class="btn alt" onclick="gameplayTrain()">训练</button></div><div class="tactic"><div><b>赛前分析对手</b><small>比赛准备度 +25 · 消耗 ¥3,000</small></div><button class="btn alt" onclick="gameplayAnalyze()">分析</button></div><div class="news"><b>目标进度</b><small>训练 ${m.training}/1 · 分析 ${m.analysis}/1 · 胜利 ${m.win}/1 · 当前准备度 ${state.prep}%</small></div></section>`}
function gameplayRender(){const old=render;render=function(){old();const p=document.querySelector('#page');if(p&&!p.querySelector('[data-gameplay-pack]')){const x=document.createElement('div');x.dataset.gameplayPack='1';x.innerHTML=gameplayPanel();p.appendChild(x)}};render()}
function gameplayTrain(){if((state.actions||0)>=3){toast('本周行动次数已用完');return}state.actions++;state.chemistry=Math.min(100,state.chemistry+3);state.morale=Math.min(100,state.morale+2);state.prep=Math.min(100,state.prep+10);state.missions.training=1;gameplaySave();toast('训练完成，比赛准备度提升');render()}
function gameplayAnalyze(){if((state.actions||0)>=3){toast('本周行动次数已用完');return}if(state.money<3000){toast('预算不足');return}state.actions++;state.money-=3000;state.prep=Math.min(100,state.prep+25);state.missions.analysis=1;state.eventsSeen++;gameplaySave();toast('对手分析完成');render()}
const gameplayMatchBase=typeof simulateMatch==='function'?simulateMatch:null;simulateMatch=function(){if(!gameplayMatchBase){toast('比赛系统正在初始化');return}const before=state.wins||0;gameplayMatchBase();if((state.wins||0)>before)state.missions.win=1;state.prep=0;gameplaySave();render()};
const gameplayWeekBase=advanceWeek;advanceWeek=function(){gameplayWeekBase();state.prep=0;state.missions={training:0,analysis:0,win:0};gameplaySave();render()};
gameplayRender();

// Team visibility: show a real starting five in the management view.

const teamVisibleRender=render;render=function(){teamVisibleRender();const p=document.querySelector('#page');if(state.page!=='club'||!p||p.querySelector('[data-team-visible]'))return;const names=state.signed.slice(0,5);const box=document.createElement('section');box.className='card';box.dataset.teamVisible='1';box.innerHTML='<div class="card-head"><h2>我的战队 · VOLT Academy</h2><span class="badge">'+names.length+'/5 首发</span></div>'+names.map((n,i)=>{const x=players.find(v=>v[0]===n);return '<div class="tactic"><div><b>'+(i+1)+'. '+n+'</b><small>'+(x?x[1]+' · '+x[2]:'已注册选手')+'</small></div><span class="trend">首发</span></div>'}).join('')+'<button class="btn alt" onclick="goRoster()">管理阵容</button>';p.prepend(box)};render();

// Inbox: make the header notification button functional.
Object.assign(state,{messages:state.messages||[{id:1,title:'VCT 官方邀请',body:'你的战队已获得下一场常规赛参赛资格。',time:'今天 09:30',read:false},{id:2,title:'选手经纪人来信',body:'nobody 的经纪团队希望讨论续约方案。',time:'昨天 18:20',read:false},{id:3,title:'训练室报告',body:'本周团队训练完成度良好，化学反应有所提升。',time:'周一 14:10',read:false}]});
function inboxPanel(){const unread=state.messages.filter(x=>!x.read).length;return `<div class="inbox-layer" id="inbox-layer"><div class="inbox-head"><h2>消息中心</h2><button class="btn alt" onclick="markMessagesRead()">全部已读</button><button class="close-inbox" onclick="closeInbox()">×</button></div><div class="inbox-count">${unread} 条未读消息</div>${state.messages.map(x=>`<button class="message-item ${x.read?'read':''}" onclick="openMessage(${x.id})"><span class="message-dot"></span><div><b>${x.title}</b><small>${x.body}</small><em>${x.time}</em></div></button>`).join('')}</div>`}
function openInbox(){if(document.querySelector('#inbox-layer'))return;const x=document.createElement('div');x.innerHTML=inboxPanel();document.body.appendChild(x.firstElementChild)}
function closeInbox(){document.querySelector('#inbox-layer')?.remove()}
function openMessage(id){const m=state.messages.find(x=>x.id===id);if(!m)return;m.read=true;save();const text=document.querySelector('#inbox-layer .inbox-count');if(text)text.textContent=state.messages.filter(x=>!x.read).length+' 条未读消息';document.querySelectorAll('#inbox-layer .message-item').forEach(b=>b.classList.toggle('read',state.messages.find(x=>x.id===+b.getAttribute('onclick').match(/d+/)[0])?.read));toast(m.title+'：'+m.body)}
function markMessagesRead(){state.messages.forEach(x=>x.read=true);save();document.querySelectorAll('#inbox-layer .message-item').forEach(x=>x.classList.add('read'));const c=document.querySelector('#inbox-layer .inbox-count');if(c)c.textContent='0 条未读消息';toast('消息已全部标记为已读')}
const notify=document.querySelector('.notify');if(notify)notify.onclick=openInbox;

// Live match mode: interactive rounds instead of an instant random result.
state.liveMatch=state.liveMatch||null;
const scheduleBeforeLive=schedule;
schedule=function(){const html=scheduleBeforeLive();return html.replace('onclick="simulateMatch()">模拟下一场','onclick="startLiveMatch()">进入比赛');};
function startLiveMatch(){if(state.liveMatch){openLiveMatch();return}if((state.actions||0)<1){toast('请先完成训练、分析或其他赛前准备');return}state.liveMatch={map:'莲华古城',round:0,score:0,enemy:0,log:['比赛开始：选择你的回合战术'],used:false};openLiveMatch()}
function openLiveMatch(){const m=state.liveMatch;if(!m)return;document.querySelector('#live-match')?.remove();const x=document.createElement('div');x.id='live-match';x.className='inbox-layer match-layer';x.innerHTML='<div class="inbox-head"><h2>VCT CN · '+m.map+' · BO1</h2><button class="close-inbox" onclick="closeLiveMatch()">×</button></div><div class="match-scoreboard"><span>VOLT Academy</span><strong>'+m.score+' : '+m.enemy+'</strong><span>Nova Esports</span></div><div class="news"><b>第 '+(m.round+1)+' 回合</b><small>'+(m.round<12?'上半场 · 手枪/经济回合':'下半场 · 决胜阶段')+'　准备度 '+(state.prep||0)+'%　士气 '+(state.morale||0)+'</small></div><div class="tactic"><div><b>快攻</b><small>高风险高收益，适合打乱对手节奏</small></div><button class="btn alt" onclick="playLiveRound(\'rush\')">执行</button></div><div class="tactic"><div><b>默认控图</b><small>均衡方案，稳定争夺地图控制权</small></div><button class="btn alt" onclick="playLiveRound(\'default\')">执行</button></div><div class="tactic"><div><b>慢打运营</b><small>依赖化学反应，残局能力更强</small></div><button class="btn alt" onclick="playLiveRound(\'slow\')">执行</button></div><div class="news"><b>比赛记录</b><small>'+m.log.slice(-4).reverse().join('<br>')+'</small></div>';document.body.appendChild(x)}
function playLiveRound(tactic){const m=state.liveMatch;if(!m||m.used)return;m.used=true;const chemistry=(state.chemistry||0)/100,morale=(state.morale||0)/100,prep=(state.prep||0)/100;const bonus=tactic==='rush'?.03:tactic==='slow'?.06:.05;const chance=Math.max(.15,Math.min(.85,.42+chemistry*.18+morale*.12+prep*.16+bonus-(m.round>11?.03:0)));const won=Math.random()<chance;m.round++;won?m.score++:m.enemy++;m.log.push('回合 '+m.round+'：'+(won?'你的战队拿下回合（'+tactic+'）':'Nova Esports 赢下回合（'+tactic+'）'));if(m.score>=13||m.enemy>=13){finishLiveMatch();return}m.used=false;openLiveMatch()}
function finishLiveMatch(){const m=state.liveMatch;if(!m)return;const won=m.score>m.enemy;if(won){state.wins=(state.wins||0)+1;state.reputation=(state.reputation||0)+100;state.missions=state.missions||{training:0,analysis:0,win:0};state.missions.win=1;toast('比赛胜利！ '+m.score+' : '+m.enemy)}else{state.losses=(state.losses||0)+1;state.reputation=(state.reputation||0)+20;toast('比赛失利：'+m.score+' : '+m.enemy)}state.actions=0;state.prep=0;state.log=state.log||[];state.log.unshift('VCT '+m.map+' '+m.score+' : '+m.enemy);state.liveMatch=null;gameplaySave();document.querySelector('#live-match')?.remove();render()}
function closeLiveMatch(){document.querySelector('#live-match')?.remove()}

// Dedicated team page. The game starts with an empty roster.
