if(starterIds.length===state.signed.length && starterIds.every((n,i)=>state.signed[i]===n)){state.signed=[];gameplaySave()}
club=function(){const names=state.signed.slice(0,5);let rows=names.map((n,i)=>{const x=players.find(v=>v[0]===n);return '<div class="tactic"><div><b>'+(i+1)+'. '+n+'</b><small>'+(x?x[1]+' · '+x[2]:'已注册选手')+'</small></div><button class="btn alt" onclick="releasePlayer(\''+n+'\')">释放</button></div>'}).join('');return '<div class="hero"><div><span class="eyebrow">VOLT ACADEMY · TEAM HUB</span><h2>我的战队</h2><p>这里是你的独立战队页面。签约选手后，他们会出现在本页面。</p></div><button class="btn" onclick="goRoster()">前往选手市场</button></div><div class="grid columns"><section class="card wide"><div class="card-head"><h2>首发阵容</h2><span class="badge">'+names.length+'/5</span></div>'+(rows||'<div class="empty">暂无战队选手。前往选手市场发起洽谈，组建你的首发阵容。</div>')+'</section><section class="card"><div class="card-head"><h2>战队状态</h2><span class="tag">SEASON</span></div><div class="tactic"><b>阵容人数</b><span class="trend">'+names.length+' / 5</span></div><div class="tactic"><b>比赛战绩</b><span class="trend">'+(state.wins||0)+' - '+(state.losses||0)+'</span></div><div class="tactic"><b>化学反应</b><span class="trend">'+(state.chemistry||0)+'%</span></div></section></div>'};render();

// Individual scouting attributes for every player.
const roleStats={Duelist:[86,1.18,168,76,31],Initiator:[80,1.08,148,74,27],Controller:[77,1.03,139,78,24],Sentinel:[79,1.06,142,80,29],Flex:[82,1.10,151,76,26]};
function statsFor(p,i){const r=Object.keys(roleStats).find(k=>p[2].includes(k))||'Flex',b=roleStats[r],seed=(p[0].split('').reduce((a,c)=>a+c.charCodeAt(0),0)+i*17)%13;return {aim:b[0]+seed%8,kd:(b[1]+(seed-6)/100).toFixed(2),adr:b[2]+seed*2,kast:b[3]+seed%9,clutch:b[4]+seed%12,age:18+seed%11,potential:seed>8?'S':seed>5?'A':'B',form:['低迷','稳定','火热'][seed%3]}}
function dataFor(p,i){const s=statsFor(p,i);return '<div class="player-data"><span>枪法 <b>'+s.aim+'</b></span><span>K/D <b>'+s.kd+'</b></span><span>ADR <b>'+s.adr+'</b></span><span>KAST <b>'+s.kast+'%</b></span><span>残局 <b>'+s.clutch+'%</b></span><span>年龄 <b>'+s.age+'</b></span><span>潜力 <b>'+s.potential+'</b></span><span>状态 <b>'+s.form+'</b></span></div>'}
const oldRoster=roster;roster=function(){const q=state.rosterQuery||'',region=state.rosterRegion||'全部',role=state.rosterRole||'全部',list=players.map((p,i)=>({p,i})).filter(o=>(!q||o.p.join(' ').toLowerCase().includes(q.toLowerCase()))&&(region==='全部'||o.p[4]===region)&&(role==='全部'||o.p[2].includes(role)));return oldRoster().replace(/<div class="player-foot">[\s\S]*?<\/div><\/div>/g,(m)=>{const name=(m.match(/onclick="sign\('([^']+)/)||[])[1],o=list.find(x=>x.p[0]===name);return o?dataFor(o.p,o.i)+m:m})};render();

// Expanded tournament system: calendar, standings, bracket and match center.
state.eventTab=state.eventTab||'calendar';state.tournament=state.tournament||{stage:'常规赛',points:0,played:0};state.matchHistory=state.matchHistory||[];
const tournamentTeams=['VOLT Academy','Nova Esports','Bilibili Gaming','EDward Gaming','Wolves Esports','Dragon Ranger'];
function teamRecord(name){if(name==='VOLT Academy')return {w:state.wins||0,l:state.losses||0,p:((state.wins||0)*3)};const n=name.split('').reduce((a,c)=>a+c.charCodeAt(0),0);return {w:3+n%5,l:1+(n%4),p:9+n%11}}
function tournamentTable(){return tournamentTeams.map((n,i)=>{const r=teamRecord(n);return '<div class="stand-row"><b>'+((i===0&&n!=='VOLT Academy')?i+1:i+1)+'. '+n+'</b><span>'+r.w+' - '+r.l+'</span><strong>'+r.p+' 分</strong></div>'}).join('')}
function eventCard(){return '<section class="card wide"><div class="card-head"><h2>VCT CN 2025 · 第二赛段</h2><span class="badge">'+state.tournament.stage+'</span></div><div class="event-meta"><span>赛制：BO3</span><span>常规赛 6 队</span><span>前四名晋级季后赛</span><span>当前周：'+(state.week||4)+'</span></div>'+[['JUN 18','VOLT Academy','Nova Esports','常规赛'],['JUN 24','Bilibili Gaming','VOLT Academy','常规赛'],['JUL 02','VOLT Academy','EDward Gaming','季后赛']].map((x,i)=>'<div class="schedule-row"><small>'+x[0]+'</small><b>'+x[1]+' <span class="muted">vs</span> '+x[2]+'</b><span class="badge">'+x[3]+'</span><button class="btn alt" onclick="matchPreview('+i+')">详情</button></div>').join('')+'</section>'}
schedule=function(){return '<div class="hero"><div><span class="eyebrow">VCT CN · COMPETITION CENTER</span><h2>赛事中心</h2><p>管理赛程、查看积分榜、追踪淘汰赛晋级路线。</p></div><button class="btn" onclick="startLiveMatch()">进入下一场比赛</button></div><div class="event-tabs"><button class="'+(state.eventTab==='calendar'?'active':'')+'" onclick="state.eventTab=\'calendar\';render()">赛程日历</button><button class="'+(state.eventTab==='standings'?'active':'')+'" onclick="state.eventTab=\'standings\';render()">积分榜</button><button class="'+(state.eventTab==='bracket'?'active':'')+'" onclick="state.eventTab=\'bracket\';render()">季后赛</button></div>'+(state.eventTab==='standings'?'<div class="grid columns"><section class="card wide"><div class="card-head"><h2>常规赛积分榜</h2><span class="muted">胜场 3 分 · 负场 0 分</span></div><div class="stand-head"><span>战队</span><span>战绩</span><span>积分</span></div>'+tournamentTable()+'</section><section class="card"><h2>晋级情况</h2><div class="news"><b>季后赛席位</b><small>前四名晋级，当前已完成 '+(state.tournament.played||0)+' 场</small></div></section></div>':state.eventTab==='bracket'?'<div class="grid bracket"><section class="card"><h2>半决赛</h2><div class="bracket-match">1号种子 · 待定 <b>vs</b> 4号种子 · 待定</div><div class="bracket-match">2号种子 · 待定 <b>vs</b> 3号种子 · 待定</div></section><section class="card"><h2>总决赛</h2><div class="bracket-match">半决赛胜者 <b>vs</b> 半决赛胜者</div><p class="muted">冠军：¥500,000 · 晋级国际赛事</p></section></div>': '<div class="grid columns">'+eventCard()+'<section class="card"><div class="card-head"><h2>赛季战绩</h2><span class="badge">'+(state.wins||0)+' - '+(state.losses||0)+'</span></div><div class="stat-value">'+((state.wins||0)*3)+' 分</div><p class="muted">胜率 '+(((state.wins||0)/Math.max(1,(state.wins||0)+(state.losses||0))*100).toFixed(0))+'%</p><div class="news"><b>赛事状态</b><small>常规赛进行中 · 还需完成赛前准备才能参赛</small></div></section></div>')+'<div class="card"><div class="card-head"><h2>最近结果</h2><span class="muted">'+state.matchHistory.length+' 场</span></div>'+(state.matchHistory.slice(0,5).map(x=>'<div class="news"><b>'+x.result+' · '+x.score+'</b><small>'+x.event+' · '+x.date+'</small></div>').join('')||'<p class="muted">暂无已完成赛事</p>')+'</div>'}
function matchPreview(i){const x=[['JUN 18','VOLT Academy','Nova Esports','常规赛'],['JUN 24','Bilibili Gaming','VOLT Academy','常规赛'],['JUL 02','VOLT Academy','EDward Gaming','季后赛']][i];toast(x[0]+' · '+x[1]+' vs '+x[2]+' · '+x[3]+' · BO3')};
const finishLiveBefore=finishLiveMatch;finishLiveMatch=function(){const m=state.liveMatch,score=m?m.score+' : '+m.enemy:'';finishLiveBefore();if(m){state.tournament.played=(state.tournament.played||0)+1;state.tournament.points+=(m.score>m.enemy?3:0);state.matchHistory.unshift({event:'VCT CN 2025 · 第二赛段',result:m.score>m.enemy?'胜利':'失利',score,date:'第 '+state.week+' 周'});gameplaySave()}};
