// Management expansion: staff, facilities, sponsors and fan progression.
function ensureWorldState(){state.staff=state.staff||{coach:0,analyst:0,scout:0};state.sponsors=state.sponsors||[];state.fans=Number.isFinite(state.fans)?state.fans:1200;state.facility=state.facility||{training:1,analysis:1,academy:1}}
function hireStaff(type){ensureWorldState();const cost={coach:18000,analyst:15000,scout:12000}[type];if((state.money||0)<cost)return toast('预算不足');if(state.staff[type]>=3)return toast('该岗位已满级');state.money-=cost;state.staff[type]++;state.morale=Math.min(100,(state.morale||60)+3);save();render();toast(type+' 等级提升至 '+state.staff[type])}
function upgradeFacility2(type){ensureWorldState();const lv=state.facility[type]||1,cost=lv*30000;if((state.money||0)<cost)return toast('预算不足，需要 ¥'+cost.toLocaleString());if(lv>=5)return toast('设施已经满级');state.money-=cost;state.facility[type]=lv+1;state.teamRating=(state.teamRating||50)+2;save();render();toast('设施升级完成')}
function signSponsor2(name,pay){ensureWorldState();if(state.sponsors.includes(name))return toast('已经签约该赞助商');state.sponsors.push(name);state.money=(state.money||0)+pay;state.fans+=300;save();render();toast('已签约 '+name+'，获得 ¥'+pay.toLocaleString())}
function staffPanel(){ensureWorldState();return `<section class="card wide"><div class="card-head"><h2>运营团队与设施</h2><span class="badge">粉丝 ${state.fans.toLocaleString()}</span></div><div class="grid-3"><div><b>教练组 Lv.${state.staff.coach}</b><p class="muted">提升训练与比赛准备效率</p><button class="btn alt" onclick="hireStaff('coach')">聘用 / 升级 ¥18,000</button></div><div><b>数据分析师 Lv.${state.staff.analyst}</b><p class="muted">增强赛前分析效果</p><button class="btn alt" onclick="hireStaff('analyst')">聘用 / 升级 ¥15,000</button></div><div><b>全球球探 Lv.${state.staff.scout}</b><p class="muted">提高高潜选手发现率</p><button class="btn alt" onclick="hireStaff('scout')">聘用 / 升级 ¥12,000</button></div></div><div class="facility-mini"><span>训练室 Lv.${state.facility.training} <button class="btn alt" onclick="upgradeFacility2('training')">升级</button></span><span>分析室 Lv.${state.facility.analysis} <button class="btn alt" onclick="upgradeFacility2('analysis')">升级</button></span><span>青训基地 Lv.${state.facility.academy} <button class="btn alt" onclick="upgradeFacility2('academy')">升级</button></span></div></section>`}
function sponsorPanel(){ensureWorldState();return `<section class="card wide"><div class="card-head"><h2>商业合作</h2><span class="badge">已签约 ${state.sponsors.length}</span></div><div class="sponsor-list"><div><b>Neon Energy</b><small>签约奖金 ¥35,000 · 粉丝 +300</small><button class="btn alt" onclick="signSponsor2('Neon Energy',35000)">洽谈</button></div><div><b>Kingdom Gear</b><small>签约奖金 ¥50,000 · 粉丝 +300</small><button class="btn alt" onclick="signSponsor2('Kingdom Gear',50000)">洽谈</button></div><div><b>VCT Broadcast</b><small>签约奖金 ¥80,000 · 粉丝 +300</small><button class="btn alt" onclick="signSponsor2('VCT Broadcast',80000)">洽谈</button></div></div></section>`}
const eventCardWithWorld=eventCard;eventCard=function(){ensureWorldState();return eventCardWithWorld()+staffPanel()+sponsorPanel()};
render();

// Fan engagement and matchday economy layer.
function ensureFanState(){state.fans=Number.isFinite(state.fans)?state.fans:1200;state.fanLevel=state.fanLevel||1;state.ticketPrice=state.ticketPrice||80;state.engagement=state.engagement||{social:0,media:0,community:0};state.homeMatches=state.homeMatches||0}
function fanAction(type){ensureFanState();const cost={social:0,media:3000,community:5000}[type];if((state.money||0)<cost)return toast('资金不足');if(cost)state.money-=cost;const gain={social:120,media:240,community:420}[type];state.fans+=gain;state.engagement[type]++;state.reputation=Math.min(100,(state.reputation||20)+({social:1,media:2,community:3}[type]));if(state.fans>=state.fanLevel*2000)state.fanLevel++;save();render();toast('粉丝 +'+gain)}
function setTicketPrice(v){ensureFanState();state.ticketPrice=Number(v);save();render()}
function matchdayRevenue(){ensureFanState();const base=state.fans*0.08*state.ticketPrice;return Math.round(base)}
function fanPanel(){ensureFanState();return `<section class="card wide"><div class="card-head"><h2>粉丝与比赛日运营</h2><span class="badge">Lv.${state.fanLevel} · ${state.fans.toLocaleString()} 粉丝</span></div><div class="grid-3"><div><b>社交媒体运营</b><p class="muted">免费发布训练花絮，稳定增加关注。</p><button class="btn alt" onclick="fanAction('social')">发布内容 · 粉丝 +120</button></div><div><b>赛前媒体日</b><p class="muted">花费 ¥3,000，提升赛事曝光。</p><button class="btn alt" onclick="fanAction('media')">举办媒体日</button></div><div><b>社区活动</b><p class="muted">花费 ¥5,000，提升声望和忠诚度。</p><button class="btn alt" onclick="fanAction('community')">举办社区活动</button></div></div><div class="economy-bar"><label>主场票价</label><input type="range" min="30" max="180" step="10" value="${state.ticketPrice}" oninput="setTicketPrice(this.value)"><b>¥${state.ticketPrice}</b><span class="muted">预计比赛日收入 ¥${matchdayRevenue().toLocaleString()}</span></div></section>`}
const eventCardWithFans=eventCard;eventCard=function(){return eventCardWithFans()+fanPanel()};
render();

// Match detail expansion: veto, economy, momentum, timeouts and round statistics.
const openLiveMatchBase=openLiveMatch;
function matchDetailPanel(){const m=state.liveMatch;if(!m)return '';m.stats=m.stats||{kills:0,deaths:0,firstKills:0,clutches:0};m.timeouts=m.timeouts??2;const economy=m.round<2?'手枪局':(m.score>m.enemy?'优势经济':'经济博弈');const momentum=m.score-m.enemy;const form=state.signed?.length?Math.min(100,55+(state.chemistry||0)*.25+(state.prep||0)*.15):35;return `<div class="match-detail"><div class="detail-grid"><div><small>地图选择</small><b>${m.map||'莲华古城'}</b><span>首图 · 双方已确认</span></div><div><small>当前经济</small><b>${economy}</b><span>战术执行会影响下回合经济</span></div><div><small>比赛势头</small><b>${momentum>0?'VOLT 占优':momentum<0?'对手占优':'势均力敌'}</b><span>${momentum>0?'士气正在上升':'保持冷静，等待翻盘'}</span></div><div><small>阵容状态</small><b>${form}%</b><span>化学反应与准备度综合评估</span></div></div><div class="match-actions"><button class="btn alt" onclick="useMatchTimeout()">暂停 (${m.timeouts})</button><button class="btn alt" onclick="requestTacticalPause()">战术暂停</button><span class="muted">回合 ${m.round} · 剩余行动 ${Math.max(0,24-m.round)}</span></div><div class="round-stats"><b>比赛统计</b><span>击杀 ${m.stats.kills}</span><span>阵亡 ${m.stats.deaths}</span><span>首杀 ${m.stats.firstKills}</span><span>残局 ${m.stats.clutches}</span></div></div>`}
function useMatchTimeout(){const m=state.liveMatch;if(!m||m.timeouts<=0)return toast('暂停次数已用完');m.timeouts--;m.timeoutBonus=.08;m.log.push('VOLT 使用暂停，重新调整战术');openLiveMatch()}
function requestTacticalPause(){const m=state.liveMatch;if(!m)return;state.prep=Math.min(100,(state.prep||0)+8);m.log.push('教练组完成战术复盘，准备度 +8');openLiveMatch()}
openLiveMatch=function(){openLiveMatchBase();const box=document.querySelector('#live-match');if(!box)return;box.querySelector('.match-detail')?.remove();box.insertAdjacentHTML('beforeend',matchDetailPanel())};
const playLiveRoundBase=playLiveRound;
playLiveRound=function(tactic){const m=state.liveMatch;if(m){m.stats=m.stats||{kills:0,deaths:0,firstKills:0,clutches:0};const before=m.score;playLiveRoundBase(tactic);if(state.liveMatch){const won=state.liveMatch.score>before;state.liveMatch.stats.kills+=won?Math.floor(10+Math.random()*8):Math.floor(5+Math.random()*7);state.liveMatch.stats.deaths+=won?Math.floor(5+Math.random()*7):Math.floor(10+Math.random()*8);if(won&&Math.random()<.42)state.liveMatch.stats.firstKills++;if(won&&Math.random()<.12)state.liveMatch.stats.clutches++}}};
render();

// Dedicated coaching department: coaches are staff, never player roster members.
const coachProfiles={strategist:{name:'Mira Chen',role:'战术教练',salary:18000,focus:'战术执行',bonus:'提升准备度与暂停效果'},head:{name:'Alex Ryu',role:'主教练',salary:26000,focus:'团队管理',bonus:'提升士气与化学反应'},analyst:{name:'Noah Silva',role:'比赛分析师',salary:15000,focus:'数据分析',bonus:'提升对手研究与经济判断'}};
function ensureCoachState(){state.coaching=state.coaching||{head:null,strategist:null,analyst:null,session:0,plan:'default'};state.coaching.session=state.coaching.session||0}
function hireCoach(slot){ensureCoachState();const c=coachProfiles[slot];if(!c)return;if(state.coaching[slot])return toast('该教练岗位已经有人');if((state.money||0)<c.salary)return toast('预算不足，无法签约教练');state.money-=c.salary;state.coaching[slot]={...c,hiredWeek:state.week||1,contract:12};save();render();toast(c.name+' 已加入教练组，不占用选手名额')}
function releaseCoach(slot){ensureCoachState();if(!state.coaching[slot])return toast('该岗位暂无教练');const name=state.coaching[slot].name;state.coaching[slot]=null;save();render();toast(name+' 已离开教练组')}
function setCoachPlan(plan){ensureCoachState();state.coaching.plan=plan;state.coaching.session++;if(plan==='attack')state.prep=Math.min(100,(state.prep||0)+10);if(plan==='defense')state.morale=Math.min(100,(state.morale||0)+6);if(plan==='review')state.chemistry=Math.min(100,(state.chemistry||0)+5);save();render();toast('教练组已安排本周计划')}
function coachPanel(){ensureCoachState();const c=state.coaching;const card=(slot,label)=>{const x=c[slot],p=coachProfiles[slot];return `<div class="coach-card"><b>${label}</b>${x?`<strong>${x.name}</strong><small>${x.role} · 周薪 ¥${x.salary.toLocaleString()}</small><small>${x.bonus}</small><button class="btn danger" onclick="releaseCoach('${slot}')">解约</button>`:`<strong>职位空缺</strong><small>${p.role} · 周薪 ¥${p.salary.toLocaleString()}</small><small>${p.bonus}</small><button class="btn alt" onclick="hireCoach('${slot}')">签约教练</button>`}</div>`};return `<section class="card wide coaching-dept"><div class="card-head"><h2>教练组</h2><span class="badge">独立于选手阵容</span></div><p class="muted">教练不参与选手注册、首发和替补名额，只负责战术、训练、分析和团队管理。</p><div class="coach-grid">${card('head','主教练')}${card('strategist','战术教练')}${card('analyst','比赛分析师')}</div><div class="coach-plans"><b>本周教练计划</b><button class="btn alt" onclick="setCoachPlan('attack')">进攻体系 · 准备度 +10</button><button class="btn alt" onclick="setCoachPlan('defense')">防守体系 · 士气 +6</button><button class="btn alt" onclick="setCoachPlan('review')">录像复盘 · 化学反应 +5</button><span class="muted">已完成 ${c.session} 次教练会议</span></div></section>`}
const eventCardWithCoaching=eventCard;eventCard=function(){return eventCardWithCoaching()+coachPanel()};
render();

// Manual map veto/pick and focused training room.
const mapPool=['亚海悬城','深海明珠','森寒冬港','微风岛屿','莲华古城','日落之城','霓虹町','裂变峡谷','幽邃地窟','隐世修所','源工重镇','沿海矿镇'];
function ensurePrepState(){state.mapDraft=state.mapDraft||{bans:[],picks:[],step:0,locked:false};state.training=state.training||{sessions:0,focus:'aim',fatigue:0,skills:{aim:50,utility:50,teamplay:50,clutch:50}}}
function resetMapDraft(){ensurePrepState();state.mapDraft={bans:[],picks:[],step:0,locked:false};save();render();toast('地图 BP 已重置')}
function mapAction(map){ensurePrepState();const d=state.mapDraft;if(d.locked||d.step>=5)return;if(d.bans.includes(map)||d.picks.includes(map))return toast('这张地图已经处理');if(d.step<3){d.bans.push(map);d.step++;toast('已禁用 '+map)}else{d.picks.push(map);d.step++;toast('已选择 '+map)}if(d.step>=5)d.locked=true;save();render()}
function confirmMapDraft(){ensurePrepState();const d=state.mapDraft;if(d.picks.length<2)return toast('至少选择两张地图');d.locked=true;state.liveMap=d.picks[0];save();render();toast('地图 BP 确认：'+d.picks.join('、'))}
function trainFocus(focus){ensurePrepState();if((state.actions||0)<1)return toast('本周训练行动点已用完');const gain={aim:4,utility:4,teamplay:5,clutch:3}[focus];state.actions--;state.training.sessions++;state.training.focus=focus;state.training.fatigue=Math.min(100,state.training.fatigue+({aim:8,utility:7,teamplay:6,clutch:5}[focus]));state.training.skills[focus]=Math.min(100,state.training.skills[focus]+gain);state.prep=Math.min(100,(state.prep||0)+({aim:3,utility:4,teamplay:6,clutch:2}[focus]));state.chemistry=Math.min(100,(state.chemistry||0)+(focus==='teamplay'?3:0));save();render();toast('训练完成：'+focus+' +'+gain)}
function restTraining(){ensurePrepState();state.training.fatigue=Math.max(0,state.training.fatigue-25);state.morale=Math.min(100,(state.morale||0)+3);save();render();toast('队伍休整完成，疲劳降低')}
function mapDraftPanel(){ensurePrepState();const d=state.mapDraft;const remaining=mapPool.filter(x=>!d.bans.includes(x)&&!d.picks.includes(x));return `<section class="card wide"><div class="card-head"><h2>赛前地图 BP</h2><span class="badge">${d.locked?'已锁定':'第 '+(d.step+1)+' / 5 步'}</span></div><p class="muted">手动禁用 3 张地图，再选择 2 张地图。地图池包含无畏契约全部正式地图，确认后首图将用于下一场比赛。</p><div class="bp-state"><div><b>禁用</b><span>${d.bans.join(' · ')||'暂无'}</span></div><div><b>选择</b><span>${d.picks.join(' · ')||'暂无'}</span></div></div><div class="map-grid">${remaining.map(m=>`<button class="map-btn" onclick="mapAction('${m}')">${m}<small>${d.step<3?'禁用':'选择'}</small></button>`).join('')}</div><button class="btn alt" onclick="confirmMapDraft()">确认地图 BP</button> <button class="btn alt" onclick="resetMapDraft()">重置</button></section>`}
function trainingPanel(){ensurePrepState();const t=state.training;return `<section class="card wide"><div class="card-head"><h2>训练中心</h2><span class="badge">训练 ${t.sessions} 次 · 疲劳 ${t.fatigue}</span></div><div class="skill-bars">${Object.entries(t.skills).map(([k,v])=>`<div><span>${{aim:'枪法',utility:'道具',teamplay:'团队协同',clutch:'残局'}[k]}</span><i><em style="width:${v}%"></em></i><b>${v}</b></div>`).join('')}</div><div class="training-actions"><button class="btn alt" onclick="trainFocus('aim')">枪法训练</button><button class="btn alt" onclick="trainFocus('utility')">道具训练</button><button class="btn alt" onclick="trainFocus('teamplay')">协同训练</button><button class="btn alt" onclick="trainFocus('clutch')">残局训练</button><button class="btn alt" onclick="restTraining()">全队休整</button></div></section>`}
const eventCardWithPrep=eventCard;eventCard=function(){return eventCardWithPrep()+mapDraftPanel()+trainingPanel()};
render();
// Training mode and realistic player economy layer.
const virtualPlayers=[['voltA','林曜','Duelist','VOLT Academy','CN','¥80k'],['voltB','周砚','Initiator','VOLT Academy','CN','¥72k'],['voltC','沈拓','Controller','VOLT Academy','CN','¥68k'],['voltD','顾言','Sentinel','VOLT Academy','CN','¥64k'],['voltE','许衡','Flex','VOLT Academy','CN','¥60k']];
players.push(...virtualPlayers);
const playerRatings={voltA:72,voltB:70,voltC:68,voltD:67,voltE:65};
function playerRating(p){if(playerRatings[p[0]]!==undefined)return playerRatings[p[0]];const n=parseInt(String(p[5]).replace(/[^0-9]/g,''))||100;return Math.max(60,Math.min(94,Math.round(55+n/14)))}
function playerValue(p){return parseInt(String(p[5]).replace(/[^0-9]/g,''))*1000}
if(!localStorage.getItem('volt-save')){state.signed=virtualPlayers.map(p=>p[0]);state.money=1250000;save()}
const rosterBase=roster;
roster=function(){const q=state.rosterQuery||'',region=state.rosterRegion||'全部',role=state.rosterRole||'全部';const list=players.filter(p=>(!q||p.join(' ').toLowerCase().includes(q.toLowerCase()))&&(region==='全部'||p[4]===region)&&(role==='全部'||p[2].includes(role)));return `<div class="hero"><div><span class="eyebrow">GLOBAL VCT DATABASE · ${players.length} PLAYERS</span><h2>全球选手市场</h2><p>综合评分、合同价格与现实竞技水平挂钩；高水平选手身价更高。</p></div><button class="btn" onclick="refreshScouting()">刷新球探报告</button></div><div class="tabs"><input class="search" placeholder="搜索 ID、姓名或战队" value="${q}" oninput="state.rosterQuery=this.value;render()"><button onclick="state.rosterRegion='全部';render()">全部 ${players.length}</button><button onclick="state.rosterRegion='CN';render()">CN</button><button onclick="state.rosterRegion='Pacific';render()">Pacific</button><button onclick="state.rosterRegion='EMEA';render()">EMEA</button><button onclick="state.rosterRegion='Americas';render()">Americas</button></div><div class="tabs"><button onclick="state.rosterRole='全部';render()">全部定位</button><button onclick="state.rosterRole='Duelist';render()">决斗者</button><button onclick="state.rosterRole='Initiator';render()">发起者</button><button onclick="state.rosterRole='Controller';render()">控场者</button><button onclick="state.rosterRole='Sentinel';render()">哨卫</button><span class="muted">找到 ${list.length} 名选手 · 已签约 ${state.signed.length} 人</span></div><div class="grid player-grid">${list.map(p=>`<div class="card player"><div class="player-top"><div class="portrait">${p[0][0].toUpperCase()}</div><div><h3>${p[0]}</h3><small>${p[1]} · ${p[3]}</small><div class="role">${p[2]} · ${p[4]}</div></div></div><div class="news"><b>综合评分 ${state.playerRatings?.[p[0]]||playerRating(p)}</b><small>枪法与协同能力按职业联赛水平估算</small></div><div class="player-foot"><span>¥${playerValue(p).toLocaleString()} / 年</span><button class="btn alt" onclick="sign('${p[0]}')">${state.signed.includes(p[0])?'已签约':'发起洽谈'}</button></div></div>`).join('')}</div>`}
const signBase=sign;
sign=function(name){const p=players.find(x=>x[0]===name);if(!p)return;if(state.signed.includes(name))return toast('该选手已经签约');if(state.signed.length>=5)return toast('首发阵容已满，请先释放一名选手');const cost=playerValue(p);if(state.money<cost)return toast('预算不足，无法完成签约');state.money-=cost;state.signed.push(name);state.chemistry=Math.min(100,(state.chemistry||0)+3);state.reputation=(state.reputation||0)+25;save();toast('已签约 '+name+'，年薪 ¥'+cost.toLocaleString());render()}
function ensureTrainingMode(){state.trainingMode=state.trainingMode||{mode:'team',target:'voltA'};state.playerRatings=state.playerRatings||{...playerRatings}}
function runTraining(mode,focus){ensureTrainingMode();if((state.actions||0)<1)return toast('本周训练行动点已用完');const cost=mode==='individual'?3000:8000;if((state.money||0)<cost)return toast('预算不足，训练需要 ¥'+cost.toLocaleString());state.actions--;state.money-=cost;state.trainingMode.mode=mode;const gain=focus==='teamplay'?2:1;if(mode==='individual'){const id=state.trainingMode.target;state.playerRatings[id]=Math.min(99,(state.playerRatings[id]||60)+gain+1)}else{state.chemistry=Math.min(100,(state.chemistry||0)+4);state.prep=Math.min(100,(state.prep||0)+8)}state.training=state.training||{sessions:0,fatigue:0,skills:{}};state.training.sessions++;state.training.fatigue=Math.min(100,(state.training.fatigue||0)+(mode==='individual'?5:10));save();render();toast((mode==='individual'?'个人':'全队')+'训练完成，费用 ¥'+cost.toLocaleString())}
function trainingModePanel(){ensureTrainingMode();const roster=state.signed.map(id=>players.find(p=>p[0]===id)).filter(Boolean);return `<section class="card wide"><div class="card-head"><h2>训练模式</h2><span class="badge">职业化训练计划</span></div><p class="muted">全队训练提升化学反应；个人训练提升选手综合评分。训练费用、疲劳和行动点都会影响赛季管理。</p><div class="tabs"><button class="btn alt" onclick="runTraining('team','teamplay')">全队战术训练 · ¥8,000</button><button class="btn alt" onclick="runTraining('team','aim')">全队枪法训练 · ¥8,000</button></div><div class="tactic"><label>个人训练对象</label><select onchange="ensureTrainingMode();state.trainingMode.target=this.value;save();render()">${roster.map(p=>`<option value="${p[0]}" ${state.trainingMode.target===p[0]?'selected':''}>${p[0]} · ${p[1]} · 评分 ${state.playerRatings[p[0]]||playerRating(p)}</option>`).join('')}</select><button class="btn alt" onclick="runTraining('individual','aim')">个人强化 · ¥3,000</button></div></section>`}
tactics=function(){return `<div class="hero"><div><span class="eyebrow">TRAINING LAB · WEEK ${state.week}</span><h2>训练与战术实验室</h2><p>根据阵容情况安排全队或个人训练，培养选手并管理训练成本。</p></div></div>${trainingModePanel()}${trainingPanel()}`};
render();// VCT rules and competitive gameplay update.
const VCT_RULES={series:'BO3',regulation:13,overtimeAt:12,maxMaps:3,regularSeasonPoints:'胜者3分，负者0分',playoffs:'常规赛前四晋级，半决赛BO3，总决赛BO5'};
function vctEnsure(){state.vct=state.vct||{mapIndex:0,seriesV:0,seriesO:0,mapScores:[],maps:[]};state.mapDraft=state.mapDraft||{bans:[],picks:[],step:0,locked:false};state.tournament=state.tournament||{stage:'常规赛',points:0,played:0};state.matchHistory=state.matchHistory||[]}
function vctMaps(){vctEnsure();const p=state.mapDraft.picks||[];return p.length>=2?p.slice(0,3):['莲华古城','沿海矿镇','深海明珠']}
function vctTeamRating(){const ids=state.signed||[];if(ids.length<5)return 45;return ids.reduce((sum,id)=>{const p=players.find(x=>x[0]===id);return sum+(state.playerRatings?.[id]||playerRating(p)||60)},0)/ids.length}
function vctOpponentRating(){return 73+((state.week||1)%5)}
function startLiveMatch(){vctEnsure();if(state.liveMatch){openLiveMatch();return}if((state.signed||[]).length<5)return toast('正式 VCT 比赛需要完整的 5 人首发阵容');if((state.actions||0)<1)return toast('请先完成训练、分析或其他赛前准备');const maps=vctMaps();state.liveMatch={map:maps[0],maps,mapIndex:0,round:0,score:0,enemy:0,seriesV:0,seriesO:0,mapScores:[],log:['BO3 系列赛开始：首图 '+maps[0]],used:false};openLiveMatch()}
function openLiveMatch(){const m=state.liveMatch;if(!m)return;document.querySelector('#live-match')?.remove();const x=document.createElement('div');x.id='live-match';x.className='inbox-layer match-layer';const ot=m.score>=12&&m.enemy>=12?'加时赛':'常规回合';x.innerHTML=`<div class="inbox-head"><h2>VCT CN · ${m.map} · BO3</h2><button class="close-inbox" onclick="closeLiveMatch()">×</button></div><div class="match-scoreboard"><span>VOLT Academy</span><strong>${m.seriesV} : ${m.seriesO}</strong><span>系列赛比分</span></div><div class="news"><b>第 ${m.round+1} 回合 · ${ot}</b><small>地图 ${m.mapIndex+1}/${m.maps.length} · 当前地图 ${m.score} : ${m.enemy} · 准备度 ${state.prep||0}% · 士气 ${state.morale||0}</small></div><div class="tactic"><b>快攻</b><small>高风险，依赖枪法；进攻方更容易拿到首杀</small><button class="btn alt" onclick="playLiveRound('rush')">执行</button></div><div class="tactic"><b>默认控图</b><small>均衡争夺地图控制权，适合经济局</small><button class="btn alt" onclick="playLiveRound('default')">执行</button></div><div class="tactic"><b>慢打运营</b><small>降低波动，依赖协同和残局能力</small><button class="btn alt" onclick="playLiveRound('slow')">执行</button></div><div class="news"><b>比赛记录</b><small>${m.log.slice(-5).reverse().join('<br>')}</small></div>`;document.body.appendChild(x)}
function playLiveRound(tactic){const m=state.liveMatch;if(!m||m.used)return;m.used=true;const team=vctTeamRating(),opp=vctOpponentRating();const tacticBonus={rush:2,default:4,slow:3}[tactic];const prep=(state.prep||0)*.10,chem=(state.chemistry||0)*.08,morale=(state.morale||0)*.05;let chance=.38+(team-opp)*.018+tacticBonus*.01+prep*.01+chem*.01+morale*.01;chance=Math.max(.18,Math.min(.82,chance));const won=Math.random()<chance;m.round++;if(won)m.score++;else m.enemy++;m.log.push(`地图 ${m.map} · 回合 ${m.round}：${won?'VOLT 拿下回合':'对手拿下回合'}（${tactic}）`);const normalEnd=(m.score>=13||m.enemy>=13)&&Math.abs(m.score-m.enemy)>=1;const overtimeEnd=m.score>=14||m.enemy>=14;if(normalEnd||overtimeEnd){const mapWon=m.score>m.enemy;if(mapWon)m.seriesV++;else m.seriesO++;m.mapScores.push(`${m.map} ${m.score}:${m.enemy}`);m.maps[m.mapIndex+1]&&(m.mapIndex++,m.map=m.maps[m.mapIndex],m.round=0,m.score=0,m.enemy=0);if(m.seriesV>=2||m.seriesO>=2){finishLiveMatch();return}m.log.push('进入下一张地图：'+m.map)}m.used=false;openLiveMatch()}
function finishLiveMatch(){const m=state.liveMatch;if(!m)return;const won=m.seriesV>m.seriesO;won?state.wins=(state.wins||0)+1:state.losses=(state.losses||0)+1;state.reputation=(state.reputation||0)+(won?100:20);state.actions=0;state.prep=0;state.morale=Math.max(0,(state.morale||0)+(won?4:-4));state.tournament=state.tournament||{stage:'常规赛',points:0,played:0};state.tournament.played++;if(won)state.tournament.points+=3;state.matchHistory=state.matchHistory||[];state.matchHistory.unshift({event:'VCT CN · '+VCT_RULES.series,result:won?'胜利':'失利',score:m.seriesV+' : '+m.seriesO+'（'+m.mapScores.join('、')+'）',date:'第 '+state.week+' 周'});state.log=state.log||[];state.log.unshift('VCT BO3 '+m.seriesV+' : '+m.seriesO);state.liveMatch=null;save();document.querySelector('#live-match')?.remove();toast((won?'系列赛胜利！':'系列赛失利：')+m.seriesV+' : '+m.seriesO);render()}
const vctRulesPanel=()=>`<section class="card wide"><div class="card-head"><h2>VCT 赛事规则</h2><span class="badge">Competitive Format</span></div><div class="grid-3"><div><b>常规赛</b><small>BO3 · 胜者 3 分 · 负者 0 分</small></div><div><b>地图规则</b><small>禁用 3 张，选择至少 2 张地图</small></div><div><b>回合规则</b><small>单图 13 胜；12:12 后进入加时</small></div></div><p class="muted">常规赛结束后积分榜前四晋级季后赛；半决赛 BO3，总决赛 BO5。完整首发和赛前准备是参加正式比赛的必要条件。</p></section>`;
const scheduleVctBase=schedule;schedule=function(){return scheduleVctBase()+vctRulesPanel()};
render();// Story campaign, tiered competition, monthly payroll/rent and sponsorship system.
const STORY_PLAYERS=[['voltA','林曜','Duelist','VOLT Academy','CN','¥80k'],['voltB','周砚','Initiator','VOLT Academy','CN','¥72k'],['voltC','沈拓','Controller','VOLT Academy','CN','¥68k'],['voltD','顾言','Sentinel','VOLT Academy','CN','¥64k'],['voltE','许衡','Flex','VOLT Academy','CN','¥60k']];
const DIVISIONS=['次级联赛','挑战者联赛','VCT CN']
const salaryOf=id=>{const p=players.find(x=>x[0]===id);return p?parseInt(String(p[5]).replace(/[^0-9]/g,''))*1000:0}
function ensureStory(){state.playerName=state.playerName||'';state.clubName=state.clubName||'VOLT Academy';state.division=state.division||'次级联赛';state.month=state.month||1;state.monthlyRent=state.monthlyRent||50000;state.sponsors=state.sponsors||[];state.sponsorIncome=state.sponsorIncome||0;state.sponsorFans=state.sponsorFans||0;state.storyFlags=state.storyFlags||{intro:false};state.contracts=state.contracts||{};state.matchHistory=state.matchHistory||[]}
function storySave(){ensureStory();localStorage.setItem('volt-save',JSON.stringify({...state,playerName:state.playerName,clubName:state.clubName,division:state.division,month:state.month,monthlyRent:state.monthlyRent,sponsors:state.sponsors,sponsorIncome:state.sponsorIncome,sponsorFans:state.sponsorFans,storyFlags:state.storyFlags,contracts:state.contracts}))}
function beginStory(name){name=(name||'').trim();if(!name)return toast('请输入你的名字');ensureStory();state.playerName=name;state.clubName=name+'电竞';state.division='次级联赛';state.month=1;state.money=1000000;state.signed=STORY_PLAYERS.map(p=>p[0]);state.contracts=Object.fromEntries(STORY_PLAYERS.map(p=>[p[0],{salary:salaryOf(p[0]),months:12}]));state.monthlyRent=50000;state.sponsorIncome=0;state.sponsors=[];state.storyFlags.intro=true;state.reputation=300;state.chemistry=55;state.prep=0;storySave();toast('梦想战队成立，次级联赛之旅开始');render()}
function storyIntro(){ensureStory();if(state.storyFlags.intro)return '';return `<section class="card story-intro"><span class="eyebrow">A NEW UNDERDOG STORY</span><h2>从零开始，打进 VCT</h2><p>你为了电竞梦想投入全部身家，签下五名年轻选手并租下训练室。扣除建队与租赁成本后，你将以 ¥1,000,000 的运营资金，从次级比赛开始。</p><div class="tactic"><label>你的名字</label><input id="player-name" class="search" placeholder="请输入玩家姓名"><button class="btn" onclick="beginStory(document.querySelector('#player-name').value)">开始我的电竞生涯</button></div><small class="muted">目标：次级联赛 → 挑战者联赛 → VCT CN</small></section>`}
function competitionInfo(){ensureStory();const data={次级联赛:['次级公开赛','BO1 小组赛，前四进入 BO3 淘汰赛','第 1 赛季：积累经验与现金流'],挑战者联赛:['Challengers CN','常规赛 BO3，积分制，前四晋级季后赛','晋级资格取决于赛季排名'],VCT:['VCT CN','官方赛区联赛 BO3，季后赛与晋级名额按赛季规则执行','目标：进入最高级别职业赛事']}[state.division];return `<section class="card wide"><div class="card-head"><h2>${data[0]}</h2><span class="badge">${state.division}</span></div><p>${data[1]}</p><small class="muted">${data[2]}</small><div class="event-meta"><span>当前赛季第 ${state.month} 月</span><span>正式比赛：完整 5 人首发</span><span>赛前准备与地图 BP 影响胜率</span></div></section>`}
function monthlyFinance(){ensureStory();const payroll=Object.values(state.contracts).reduce((s,c)=>s+(c.salary||0),0);return {payroll,rent:state.monthlyRent,income:state.sponsorIncome||0,net:(state.sponsorIncome||0)-payroll-state.monthlyRent}}
function advanceMonth(){ensureStory();const f=monthlyFinance();state.money+=(f.income||0)-(f.payroll||0)-f.rent;state.month++;Object.values(state.contracts).forEach(c=>c.months=Math.max(0,(c.months||12)-1));state.actions=3;state.prep=Math.max(0,(state.prep||0)-8);state.morale=Math.max(0,(state.morale||0)-2);storySave();toast(`第 ${state.month} 月开始：工资 ¥${f.payroll.toLocaleString()}，房租 ¥${f.rent.toLocaleString()}`);render()}
function advanceWeek(){ensureStory();state.week=(state.week||1)+1;state.actions=3;state.morale=Math.max(0,(state.morale||0)-1);if(state.week%4===0)advanceMonth();else{storySave();toast('新的一周开始了');render()}}
function availablePlayer(p){ensureStory();if(p[3]==='VOLT Academy')return true;const rating=typeof playerRating==='function'?playerRating(p):70;const cap={次级联赛:78,挑战者联赛:88,VCT:99}[state.division]||78;return rating<=cap||state.reputation>=1800}
function sign(name){ensureStory();const p=players.find(x=>x[0]===name);if(!p)return;if(!availablePlayer(p))return toast('该选手目前级别过高，需要更高赛事声望或晋级后才能洽谈');if(state.signed.includes(name))return toast('该选手已经签约');if(state.signed.length>=7)return toast('阵容最多保留 5 名首发与 2 名替补');const fee=Math.round(salaryOf(name)*0.25);if(state.money<fee)return toast('预算不足，签约保证金需要 ¥'+fee.toLocaleString());state.money-=fee;state.signed.push(name);state.contracts[name]={salary:salaryOf(name),months:12};state.chemistry=Math.min(100,(state.chemistry||0)+2);state.reputation=(state.reputation||0)+10;storySave();toast(`已签约 ${name}，保证金 ¥${fee.toLocaleString()}，月薪 ¥${salaryOf(name).toLocaleString()}`);render()}
function sponsorPanel(){ensureStory();const offers=[['社区电竞馆','¥30,000',30000,100],['硬件品牌','¥70,000',70000,250],['全国饮料品牌','¥140,000',140000,500]];return `<section class="card wide"><div class="card-head"><h2>赞助系统</h2><span class="badge">月收入 ¥${(state.sponsorIncome||0).toLocaleString()}</span></div><p class="muted">赞助合同按月提供收入和粉丝，但高额合同需要更高声望及赛事级别。每月结算一次。</p>${offers.map((o,i)=>{const locked=i===1&&state.reputation<700||i===2&&(state.reputation<1400||state.division==='次级联赛');const signed=state.sponsors.includes(o[0]);return `<div class="tactic"><div><b>${o[0]}</b><small>月赞助 ¥${o[2].toLocaleString()} · 粉丝 +${o[3]}</small></div><button class="btn alt" ${locked||signed?'disabled':''} onclick="signSponsorStory('${o[0]}',${o[2]},${o[3]})">${signed?'已签约':locked?'暂未解锁':'签约'}</button></div>`}).join('')}</section>`}
function signSponsorStory(name,income,fans){ensureStory();if(state.sponsors.includes(name))return toast('该赞助已签约');if(name==='硬件品牌'&&state.reputation<700)return toast('声望不足');if(name==='全国饮料品牌'&&(state.reputation<1400||state.division==='次级联赛'))return toast('需要挑战者联赛及更高声望');state.sponsors.push(name);state.sponsorIncome+=income;state.sponsorFans+=fans;state.money+=income;storySave();toast(`${name} 已签约，月收入增加 ¥${income.toLocaleString()}`);render()}
function storyDashboard(){ensureStory();if(!state.storyFlags.intro)return storyIntro();const f=monthlyFinance();return `<div class="hero"><div><span class="eyebrow">第 ${state.month} 月 · ${state.division}</span><h2>${state.playerName}，你的梦想正在起步。</h2><p>${state.clubName} 从次级赛场出发，目标是 VCT CN。</p></div><button class="btn" onclick="advanceWeek()">推进一周</button></div>${competitionInfo()}<div class="grid stats"><div class="card"><span class="stat-label">运营资金</span><div class="stat-value">¥${state.money.toLocaleString()}</div></div><div class="card"><span class="stat-label">月度支出</span><div class="stat-value">¥${(f.payroll+f.rent).toLocaleString()}</div><small>工资 ¥${f.payroll.toLocaleString()} · 房租 ¥${f.rent.toLocaleString()}</small></div><div class="card"><span class="stat-label">月度赞助</span><div class="stat-value">¥${f.income.toLocaleString()}</div></div><div class="card"><span class="stat-label">赛季战绩</span><div class="stat-value">${state.wins||0} - ${state.losses||0}</div></div></div>${sponsorPanel()}`}
const oldDashboard=dashboard;dashboard=storyDashboard;
const oldRosterStory=roster;roster=function(){const html=oldRosterStory();return html.replace(/<div class="hero">/,`<div class="hero"><div><span class="eyebrow">${state.division} · 选手市场规则</span><p>当前阶段不会直接开放顶级选手；先在次级赛场培养成绩与声望。</p></div></div><div class="hero">`)};
const oldSaveStory=save;save=function(){ensureStory();oldSaveStory();storySave()};
ensureStory();
render();// Reserve team and academy development system.
function ensureDevelopment(){ensureStory();state.reserve=state.reserve||[];state.academyProspects=state.academyProspects||[];state.reserveLevel=state.reserveLevel||0;state.academyLevel=state.academyLevel||0;state.academyReport=state.academyReport||'尚未生成本月报告'}
function developmentCost(type){const lv=type==='reserve'?state.reserveLevel:state.academyLevel;return (lv+1)*(type==='reserve'?250000:180000)}
function buildDevelopment(type){ensureDevelopment();const cost=developmentCost(type);if(state.money<cost)return toast(`资金不足，需要 ¥${cost.toLocaleString()}`);if(type==='reserve'){if(state.reserveLevel>=3)return toast('二队已经达到最高等级');if(state.division==='次级联赛'&&state.reputation<900)return toast('二队需要进入挑战者联赛或声望达到 900');state.reserveLevel++;state.monthlyRent+=30000;state.chemistry=Math.min(100,(state.chemistry||0)+2);toast('二队基地建设完成，月租增加 ¥30,000')}else{if(state.academyLevel>=3)return toast('青训中心已经达到最高等级');if(state.reputation<600)return toast('青训中心需要声望达到 600');state.academyLevel++;state.monthlyRent+=20000;state.academyReport='设施升级后发现率提升，可生成新的潜力选手';toast('青训中心升级完成，月租增加 ¥20,000')}state.money-=cost;storySave();render()}
function generateAcademy(){ensureDevelopment();if(!state.academyLevel)return toast('请先建设青训中心');const cost=15000*state.academyLevel;if(state.money<cost)return toast(`预算不足，需要 ¥${cost.toLocaleString()}`);if(state.academyProspects.length>=6)return toast('青训名单已满，请先签约或淘汰候选人');const roles=['Duelist','Initiator','Controller','Sentinel','Flex'];const id='academy'+Date.now();const rating=Math.min(82,60+state.academyLevel*4+Math.floor(Math.random()*8));const salary=Math.round((rating*900+state.academyLevel*5000)/1000)*1000;const p=[id,'青训新人 '+(state.academyProspects.length+1),roles[Math.floor(Math.random()*roles.length)],'VOLT Academy 青训','CN','¥'+Math.round(salary/1000)+'k'];players.push(p);state.academyProspects.push({id,rating,potential:Math.min(99,rating+8+Math.floor(Math.random()*8)),weeks:0});state.money-=cost;state.academyReport=`本月发现 ${p[1]}：评分 ${rating}，潜力 ${state.academyProspects.at(-1).potential}`;storySave();toast('发现一名青训候选人');render()}
function developProspect(id){ensureDevelopment();const x=state.academyProspects.find(v=>v.id===id),p=players.find(v=>v[0]===id);if(!x||!p)return;if((state.actions||0)<1)return toast('本周行动点已用完');const cost=5000+state.academyLevel*3000;if(state.money<cost)return toast('预算不足');state.actions--;state.money-=cost;x.weeks++;x.rating=Math.min(x.potential,x.rating+1);p[5]='¥'+Math.round((x.rating*900+state.academyLevel*5000)/1000)+'k';storySave();toast(p[1]+' 培养完成，评分提升至 '+x.rating);render()}
function promoteProspect(id){ensureDevelopment();const x=state.academyProspects.find(v=>v.id===id),p=players.find(v=>v[0]===id);if(!x||!p)return;if(!state.reserveLevel)return toast('请先建设二队，青训选手默认进入二队');if(state.reserve.length>=5)return toast('二队首发已满');state.reserve.push(id);state.academyProspects=state.academyProspects.filter(v=>v.id!==id);state.contracts[id]={salary:salaryOf(id)||60000,months:12};storySave();toast(p[1]+' 已晋升至二队');render()}
function academyPanel(){ensureDevelopment();const prospects=state.academyProspects.map(x=>{const p=players.find(v=>v[0]===x.id);return `<div class="tactic"><div><b>${p[1]}</b><small>${p[2]} · 当前评分 ${x.rating} · 潜力 ${x.potential} · 培养 ${x.weeks} 周</small></div><button class="btn alt" onclick="developProspect('${x.id}')">培养</button><button class="btn alt" onclick="promoteProspect('${x.id}')">晋升二队</button></div>`}).join('');return `<div class="hero"><div><span class="eyebrow">DEVELOPMENT DEPARTMENT</span><h2>二队与青训体系</h2><p>资金充足后建设人才梯队，培养年轻选手，避免只能依赖高价转会。</p></div></div><div class="grid columns"><section class="card"><div class="card-head"><h2>二队</h2><span class="badge">Lv.${state.reserveLevel}</span></div><p class="muted">二队可参加次级赛事并承担培养、替补和轮换任务。当前人数 ${state.reserve.length}/5。</p><p>升级费用：¥${developmentCost('reserve').toLocaleString()} · 月租增加 ¥30,000</p><button class="btn" onclick="buildDevelopment('reserve')">建设 / 升级二队</button>${state.reserve.map(id=>{const p=players.find(v=>v[0]===id);return p?`<div class="news"><b>${p[1]}</b><small>${p[2]} · 月薪 ¥${salaryOf(id).toLocaleString()}</small></div>`:''}).join('')}</section><section class="card"><div class="card-head"><h2>青训中心</h2><span class="badge">Lv.${state.academyLevel}</span></div><p class="muted">青训中心发现低成本、高潜力新人；升级后提高潜力和发现质量。</p><p>升级费用：¥${developmentCost('academy').toLocaleString()} · 月租增加 ¥20,000</p><button class="btn" onclick="buildDevelopment('academy')">建设 / 升级青训</button><button class="btn alt" onclick="generateAcademy()">生成候选人 · ¥${(15000*state.academyLevel).toLocaleString()}</button><div class="news"><b>最近报告</b><small>${state.academyReport}</small></div></section></div><section class="card wide"><div class="card-head"><h2>青训候选人</h2><span class="muted">${state.academyProspects.length}/6</span></div>${prospects||'<div class="empty">暂无候选人。建设青训中心后生成报告。</div>'}</section>`}
academy=academyPanel;
const oldClubDevelopment=club;club=function(){ensureDevelopment();const html=oldClubDevelopment();return html+`<section class="card wide"><div class="card-head"><h2>人才梯队</h2><span class="badge">二队 ${state.reserve.length}/5 · 青训 Lv.${state.academyLevel}</span></div><p class="muted">一队负责主赛场，二队负责次级赛事和培养，青训负责发掘新人。</p></section>`};
const oldMonthlyFinance=monthlyFinance;monthlyFinance=function(){ensureDevelopment();const f=oldMonthlyFinance();const reservePayroll=state.reserve.reduce((s,id)=>s+salaryOf(id),0);return {...f,payroll:f.payroll+reservePayroll,net:(f.income||0)-f.rent-f.payroll-reservePayroll}};
const oldStorySaveDevelopment=storySave;storySave=function(){ensureDevelopment();oldStorySaveDevelopment()};
ensureDevelopment();render();// Expanded management gameplay: weekly decisions, scouting, contracts, form and promotion.
function ensureMorePlay(){ensureDevelopment();state.playerMood=state.playerMood||{};state.scouting=state.scouting||{level:0,assignments:0,lastReport:'暂无球探报告'};state.season=state.season||{matches:0,wins:0,losses:0,stage:'常规赛'};state.events=state.events||[];state.renewals=state.renewals||{}}
function moreSave(){ensureMorePlay();storySave()}
function weeklyDecision(type){ensureMorePlay();if((state.actions||0)<1)return toast('本周行动点已用完');state.actions--;if(type==='review'){state.prep=Math.min(100,(state.prep||0)+12);state.chemistry=Math.min(100,(state.chemistry||0)+2);state.events.unshift('录像复盘完成：准备度 +12')}if(type==='meeting'){state.morale=Math.min(100,(state.morale||0)+8);state.reputation=(state.reputation||0)+8;state.events.unshift('团队会议完成：士气提升')}if(type==='rest'){state.morale=Math.min(100,(state.morale||0)+5);state.training=state.training||{};state.training.fatigue=Math.max(0,(state.training.fatigue||0)-25);state.events.unshift('全队休整：疲劳降低')}moreSave();toast({review:'录像复盘完成',meeting:'团队会议完成',rest:'休整完成'}[type]);render()}
function scoutAssignment(){ensureMorePlay();if((state.actions||0)<1)return toast('本周行动点已用完');const cost=10000+state.scouting.level*8000;if(state.money<cost)return toast('球探任务预算不足');state.actions--;state.money-=cost;state.scouting.assignments++;state.scouting.lastReport='球探发现：一名次级选手值得试训，建议查看低评分市场';state.reputation+=12;moreSave();toast('球探任务完成，市场报告已更新');render()}
function upgradeScouting(){ensureMorePlay();const cost=(state.scouting.level+1)*60000;if(state.money<cost)return toast('升级球探网络需要 ¥'+cost.toLocaleString());if(state.scouting.level>=3)return toast('球探网络已满级');state.money-=cost;state.scouting.level++;moreSave();toast('球探网络升级至 Lv.'+state.scouting.level);render()}
function renewContract(id){ensureMorePlay();const p=players.find(x=>x[0]===id),c=state.contracts[id];if(!p||!c)return;if(state.money<30000)return toast('续约谈判准备金不足');state.money-=30000;c.months=12;c.salary=Math.round(c.salary*1.08);state.renewals[id]=true;moreSave();toast(p[1]+' 已续约，月薪调整为 ¥'+c.salary.toLocaleString());render()}
function playerMoodValue(id){ensureMorePlay();if(state.playerMood[id]===undefined)state.playerMood[id]=70;return state.playerMood[id]}
function contractPanel(){ensureMorePlay();const rows=state.signed.map(id=>{const p=players.find(x=>x[0]===id),c=state.contracts[id]||{salary:salaryOf(id),months:12};if(!p)return '';const mood=playerMoodValue(id);return `<div class="tactic"><div><b>${p[0]} · ${p[1]}</b><small>月薪 ¥${c.salary.toLocaleString()} · 合同剩余 ${c.months} 月 · 状态 ${mood}</small></div>${c.months<=2?`<button class="btn alt" onclick="renewContract('${id}')">续约准备金 ¥30,000</button>`:'<span class="trend">合同稳定</span>'}</div>`}).join('');return `<section class="card wide"><div class="card-head"><h2>合同与更衣室</h2><span class="badge">首发 ${state.signed.length}/5</span></div><p class="muted">选手合同到期前需要续约；长期拖欠工资或连续失利会降低士气与留队意愿。</p>${rows||'<div class="empty">暂无签约选手</div>'}</section>`}
function promotionPanel(){ensureMorePlay();const s=state.season;const rate=s.matches?Math.round(s.wins/s.matches*100):0;const canPromote=s.matches>=8&&rate>=60;return `<section class="card wide"><div class="card-head"><h2>赛季目标与晋级</h2><span class="badge">${s.matches}/8 场</span></div><div class="tactic"><div><b>${state.division} 赛季战绩</b><small>${s.wins} 胜 ${s.losses} 负 · 胜率 ${rate}%</small></div>${canPromote&&state.division!=='VCT CN'?'<button class="btn" onclick="promoteDivision()">申请晋级</button>':'<span class="muted">8 场后按成绩判定</span>'}</div><p class="muted">晋级要求：完成至少 8 场赛事且胜率达到 60%。失败则继续留在当前级别，可通过下赛季重新挑战。</p></section>`}
function promoteDivision(){ensureMorePlay();if(state.season.matches<8||state.season.wins/state.season.matches<.6)return toast('当前成绩还未达到晋级标准');if(state.division==='次级联赛')state.division='挑战者联赛';else if(state.division==='挑战者联赛')state.division='VCT CN';else return toast('已经进入 VCT CN');state.season={matches:0,wins:0,losses:0,stage:'常规赛'};state.reputation+=250;state.money+=150000;moreSave();toast('晋级成功：'+state.division+'，获得联盟奖金 ¥150,000');render()}
const finishMatchMoreBase=finishLiveMatch;finishLiveMatch=function(){const before=state.liveMatch;finishMatchMoreBase();if(before){ensureMorePlay();state.season.matches++;if(before.seriesV>before.seriesO)state.season.wins++;else state.season.losses++;state.playerMood=(state.playerMood||{});(state.signed||[]).forEach(id=>{state.playerMood[id]=Math.max(20,Math.min(100,(state.playerMood[id]||70)+(before.seriesV>before.seriesO?3:-4)))});moreSave()}}
function moreGameplayPanel(){ensureMorePlay();return `<section class="card wide"><div class="card-head"><h2>每周管理决策</h2><span class="badge">剩余行动 ${state.actions||0}</span></div><div class="grid-3"><div><b>录像复盘</b><small>准备度 +12 · 化学反应 +2</small><button class="btn alt" onclick="weeklyDecision('review')">执行</button></div><div><b>团队会议</b><small>士气 +8 · 声望 +8</small><button class="btn alt" onclick="weeklyDecision('meeting')">执行</button></div><div><b>全队休整</b><small>疲劳 -25 · 士气 +5</small><button class="btn alt" onclick="weeklyDecision('rest')">执行</button></div></div><div class="tactic"><div><b>全球球探任务 Lv.${state.scouting.level}</b><small>费用 ¥${(10000+state.scouting.level*8000).toLocaleString()} · ${state.scouting.lastReport}</small></div><button class="btn alt" onclick="scoutAssignment()">派遣球探</button><button class="btn alt" onclick="upgradeScouting()">升级 ¥${((state.scouting.level+1)*60000).toLocaleString()}</button></div></section>`}
const dashboardMoreBase=dashboard;dashboard=function(){return dashboardMoreBase()+moreGameplayPanel()+promotionPanel()+contractPanel()};
const clubMoreBase=club;club=function(){return clubMoreBase()+contractPanel()};
ensureMorePlay();render();// Expanded lower-tier competition pyramid and regional league progression.
const LOWER_LEAGUES=[
 {id:'open-cup',name:'城市公开赛',division:'城市公开赛',format:'BO1 小组赛 + BO3 淘汰赛',teams:16,required:0,bonus:15000,rep:30},
 {id:'regional-open',name:'地区公开赛',division:'地区公开赛',format:'BO3 常规赛 + BO3 季后赛',teams:12,required:250,bonus:30000,rep:55},
 {id:'national-open',name:'全国公开赛',division:'全国公开赛',format:'BO3 双循环',teams:10,required:500,bonus:60000,rep:90},
 {id:'challengers',name:'Challengers CN',division:'挑战者联赛',format:'BO3 常规赛 + BO3 季后赛',teams:10,required:900,bonus:120000,rep:180},
 {id:'vct',name:'VCT CN',division:'VCT CN',format:'BO3 常规赛 + 季后赛',teams:12,required:1600,bonus:250000,rep:300}
];
function ensureLowerLeagues(){ensureMorePlay();state.leagueIndex=Number.isInteger(state.leagueIndex)?state.leagueIndex:0;state.leagueSeason=state.leagueSeason||{played:0,wins:0,losses:0,points:0};state.lowerFixtures=state.lowerFixtures||[]}
function currentLeague(){ensureLowerLeagues();return LOWER_LEAGUES[state.leagueIndex]||LOWER_LEAGUES[0]}
function resetLeagueSeason(){const l=currentLeague();state.leagueSeason={played:0,wins:0,losses:0,points:0};state.season={matches:0,wins:0,losses:0,stage:'常规赛'};state.division=l.division}
function lowerLeagueCard(){ensureLowerLeagues();const l=currentLeague(),s=state.leagueSeason,rate=s.played?Math.round(s.wins/s.played*100):0;const canPromote=s.played>=8&&rate>=60&&state.leagueIndex<LOWER_LEAGUES.length-1;return `<section class="card wide"><div class="card-head"><h2>${l.name}</h2><span class="badge">第 ${state.month||1} 月 · ${l.division}</span></div><div class="event-meta"><span>赛制：${l.format}</span><span>参赛队：${l.teams} 队</span><span>本赛季：${s.played}/8 场</span><span>积分：${s.points}</span></div><div class="tactic"><div><b>当前战绩 ${s.wins} 胜 ${s.losses} 负 · 胜率 ${rate}%</b><small>晋级要求：至少 8 场且胜率 60%</small></div>${canPromote?'<button class="btn" onclick="promoteLowerLeague()">晋级下一联赛</button>':'<span class="muted">完成赛季后解锁晋级</span>'}</div><p class="muted">赛季奖金 ¥${l.bonus.toLocaleString()} · 胜场声望 +${l.rep}。每个级别有独立赛季记录，晋级后进入新的赛程池。</p></section>`}
function lowerLeagueLadder(){ensureLowerLeagues();return `<section class="card wide"><div class="card-head"><h2>晋级阶梯</h2><span class="tag">PATH TO VCT</span></div>${LOWER_LEAGUES.map((l,i)=>`<div class="schedule-row"><b>${i+1}. ${l.name}</b><span class="muted">${l.format}</span><span class="badge">${i<=state.leagueIndex?'已解锁':'声望 '+l.required}</span></div>`).join('')}</section>`}
function lowerLeagueFixtures(){ensureLowerLeagues();const l=currentLeague();const rivals=['Phoenix Youth','Shanghai Sparks','East Harbor','Red Lantern','Vertex Union','Nanjing Nova'];return `<section class="card wide"><div class="card-head"><h2>本级联赛赛程</h2><span class="muted">${l.name} · 模拟对手</span></div>${Array.from({length:8},(_,i)=>{const opp=rivals[(i+state.week)%rivals.length];const done=i<state.leagueSeason.played;const win=done&&i<state.leagueSeason.wins;return `<div class="schedule-row"><small>第 ${i+1} 场</small><b>${state.clubName||'VOLT Academy'} <span class="muted">vs</span> ${opp}</b><span class="badge">${done?(win?'胜利':'失利'):l.format.split(' ')[0]}</span>${!done&&i===state.leagueSeason.played?'<button class="btn alt" onclick="startLowerMatch()">进入比赛</button>':''}</div>`}).join('')}</section>`}
function startLowerMatch(){ensureLowerLeagues();if(state.leagueSeason.played>=8)return toast('本赛季常规赛已经完成');if((state.signed||[]).length<5)return toast('需要完整 5 人首发');if((state.actions||0)<1)return toast('请先完成赛前准备');state.lowerMatch=true;startLiveOriginal()}
const startLiveOriginal=startLiveMatch;startLiveMatch=function(){ensureLowerLeagues();if(state.lowerMatch){state.lowerMatch=false;startLiveOriginal();return}startLiveOriginal()}
const finishLiveLowerBase=finishLiveMatch;finishLiveMatch=function(){const m=state.liveMatch;const lower=state.leagueIndex<3&&state.lowerMatch===true;finishLiveLowerBase();if(m&&lower){const won=m.seriesV>m.seriesO;state.leagueSeason.played++;if(won){state.leagueSeason.wins++;state.leagueSeason.points+=3;state.money+=(currentLeague().bonus/8);state.reputation+=currentLeague().rep}else state.leagueSeason.losses++;state.lowerMatch=false;moreSave()}}
function promoteLowerLeague(){ensureLowerLeagues();const s=state.leagueSeason;if(s.played<8||s.wins/s.played<.6)return toast('当前联赛成绩未达到晋级标准');if(state.leagueIndex>=LOWER_LEAGUES.length-1)return toast('你已经进入 VCT CN');state.leagueIndex++;state.division=currentLeague().division;state.reputation+=250;state.money+=currentLeague().bonus;resetLeagueSeason();moreSave();toast('晋级成功：'+currentLeague().name+'，获得奖金 ¥'+currentLeague().bonus.toLocaleString());render()}
const oldCompetitionInfoLower=competitionInfo;competitionInfo=function(){ensureLowerLeagues();return lowerLeagueCard()+lowerLeagueLadder()};
const oldScheduleLower=schedule;schedule=function(){ensureLowerLeagues();return oldScheduleLower()+lowerLeagueFixtures()};
const oldDashboardLower=dashboard;dashboard=function(){return oldDashboardLower()};
ensureLowerLeagues();render();